<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body"><h4><?=_l('vm_create_video_meeting')?></h4><hr><?=form_open(admin_url('video_meetings/create'))?><div class="form-group"><label><?=_l('vm_meeting_name')?></label><input class="form-control" name="title" required style="text-transform:uppercase" oninput="this.value=this.value.toUpperCase()"></div><div class="form-group"><label>Meeting Duration</label><select class="form-control" name="duration_minutes"><option value="0">Unlimited</option><option value="30">30 minutes</option><option value="45">45 minutes</option><option value="60">1 hour</option></select></div><div class="form-group"><label><?=_l('vm_invite_contacts')?></label><select class="selectpicker form-control" multiple data-live-search="true" name="contacts[]"><?php foreach($contacts as $c){?><option value="<?=$c['id']?>"><?=html_escape($c['firstname'].' '.$c['lastname'].' — '.$c['email'])?></option><?php }?></select></div><div class="form-group"><label for="vm-staff-attendees">Employee attendees</label><select id="vm-staff-attendees" class="selectpicker form-control" multiple data-live-search="true" name="staff_ids[]"><?php foreach($staff as $employee){?><option value="<?= (int)$employee['staffid'] ?>"><?= html_escape($employee['firstname'].' '.$employee['lastname'].' — '.$employee['email']) ?></option><?php }?></select><p class="help-block">Selected employees can use this meeting’s staff link after signing in. Invitations are not emailed automatically.</p></div><button class="btn btn-primary"><?=_l('vm_create_join')?></button><?=form_close()?></div></div></div></div><?php init_tail(); ?>
